import { Shape, Connection } from "./dom";
import { Rect, Point } from "./math";
/**
 * Tooltip position types.
 */
export type TooltipPosition = 'right' | 'left' | 'bottom' | 'top';
/**
 * Calculates the optimal position for a tooltip relative to a diagram shape or connection.
 *
 * This function handles coordinate transformations between document space (diagram model coordinates)
 * and view space (browser viewport coordinates), accounting for zoom and pan transformations.
 * It also performs collision detection and viewport boundary clamping.
 *
 * @param options - Configuration options for tooltip placement
 * @param options.hovered - The diagram shape or connection being hovered
 * @param options.mouse - Mouse position in document coordinates (diagram model space)
 * @param options.shapes - Array of shape bounds in document coordinates
 * @param options.connections - Array of connection polylines in document coordinates
 * @param options.diagramRect - The diagram's bounding rectangle in view space
 * @param options.zoom - Current zoom level of the diagram
 * @param options.pan - Current pan offset of the diagram (as returned by diagram.pan())
 * @param options.tooltipSize - Width and height of the tooltip element
 * @param options.viewportBounds - Browser viewport bounds for clamping
 * @returns Position object with left, top coordinates in view space and the chosen position side
 */
export declare function placeTooltip(options: {
    hovered: Shape | Connection;
    mouse: Point;
    shapes: Rect[];
    connections: Point[][];
    diagramRect: DOMRect;
    zoom: number;
    pan: Point;
    tooltipSize: {
        width: number;
        height: number;
    };
    viewportBounds: DOMRect;
}): {
    left: number;
    top: number;
    position: TooltipPosition;
};
